import { bindSetIcon, renderSetIcon } from "../icon-set-core.js";

export const definition = {
  "name": "copy",
  "category": "Files",
  "viewBox": "0 0 24 24",
  "mode": "stroke",
  "strokeWidth": 2,
  "motion": "copy",
  "parts": [
    {
      "tag": "path",
      "attrs": {
        "d": "M4 16c-1.1 0-2-.9-2-2V4c0-1.1.9-2 2-2h10c1.1 0 2 .9 2 2"
